import * as T from './vendor/three.module.js';
export function installTram({scene,camera,beforeBoard,onExit,pause,guideTo,canBoard}){
 const stops=[{id:'park',name:'Park entrance',x:0,z:36},{id:'meadow',name:'Meadow Village',x:-29,z:76},{id:'harbor',name:'Bluewater Village',x:29,z:76},{id:'woodland',name:'Woodland Village',x:0,z:116},{id:'eldergrove',name:'Eldergrove homes',x:0,z:161}];
 const mat=c=>new T.MeshStandardMaterial({color:c,roughness:.65}),green=mat('#244f46'),gold=mat('#deb45c'),cream=mat('#f5e5be'),dark=mat('#242a2b'),path=mat('#d8c9a4');
 function box(parent,x,y,z,w,h,d,m){const o=new T.Mesh(new T.BoxGeometry(w,h,d),m);o.position.set(x,y,z);o.castShadow=o.receiveShadow=true;parent.add(o);return o;}
 box(scene,3.5,.035,96,7,.13,4,path);box(scene,7,.035,106,4,.13,24,path);
 box(scene,7,.035,126,4,.13,24,path);box(scene,3.5,.035,136,7,.13,4,path);
 for(const s of stops){box(scene,s.x+2.2,.1,s.z,1.6,.18,4,cream);box(scene,s.x+3,1.5,s.z,.08,3,.08,gold);const c=document.createElement('canvas');c.width=768;c.height=192;const ctx=c.getContext('2d');ctx.fillStyle='#244f46';ctx.fillRect(0,0,768,192);ctx.fillStyle='#fff0c7';ctx.textAlign='center';ctx.font='bold 48px serif';ctx.fillText('VILLAGE TRAM',384,73);ctx.font='36px sans-serif';ctx.fillText(s.name,384,145);const texture=new T.CanvasTexture(c);texture.colorSpace=T.SRGBColorSpace;const sign=new T.Mesh(new T.PlaneGeometry(3,.75),new T.MeshStandardMaterial({map:texture,side:T.DoubleSide}));sign.position.set(s.x+3,3,s.z);scene.add(sign);}
 const car=new T.Group();car.name='Village tram';scene.add(car);box(car,0,.6,0,2.1,.35,3.8,green);box(car,0,3.05,0,2.4,.2,4.1,green);for(const x of [-1,1])for(const z of [-1.7,1.7]){box(car,x,1.9,z,.06,2.1,.06,gold);const wheel=new T.Mesh(new T.CylinderGeometry(.4,.4,.2,16),dark);wheel.rotation.z=Math.PI/2;wheel.position.set(x,.4,z*.7);car.add(wheel);}for(const x of [-.75,.75])box(car,x,1,0,.45,.15,2.8,cream);car.position.set(0,0,36);
 const $=s=>document.querySelector(s),dialog=document.createElement('dialog');dialog.id='tramMenu';dialog.setAttribute('aria-labelledby','tramTitle');const title=document.createElement('h2');title.id='tramTitle';title.textContent='Village tram';const body=document.createElement('div');body.id='tramBody';const close=document.createElement('button');close.id='tramClose';close.textContent='Close';close.onclick=()=>dialog.close();dialog.append(title,body,close);document.body.append(dialog);
 const dock=document.createElement('div');dock.id='tramRide';dock.hidden=true;const status=document.createElement('span');status.id='tramStatus';const toggle=document.createElement('button');toggle.id='tramPause';toggle.textContent='Pause';const cancel=document.createElement('button');cancel.id='tramCancel';cancel.textContent='Return to departure';dock.append(status,toggle,cancel);document.body.append(dock);
 const css=document.createElement('link');css.rel='stylesheet';css.href='tram.css';document.head.append(css);const nav=document.createElement('button');nav.id='tramButton';nav.textContent='Village tram';$('nav').append(nav);
 let ride=null,manualPause=false,lookYaw=0,lookPitch=0;
 const nearest=()=>stops.find(s=>Math.hypot(camera.position.x-s.x,camera.position.z-s.z)<4)||null;
 const forestBranch=[{x:7,z:116},{x:7,z:96},{x:0,z:96},{x:0,z:76}];
 const branch=s=>s.id==='eldergrove'?[s,{x:0,z:136},{x:7,z:136},...forestBranch]:s.id==='woodland'?[s,...forestBranch]:[s,{x:0,z:76}];
 // Join at the first shared junction, so neighboring forest stops avoid a trip back to the park.
 function route(a,b){const aa=branch(a),bb=branch(b);const ai=aa.findIndex(p=>bb.some(q=>p.x===q.x&&p.z===q.z)),bi=bb.findIndex(q=>q.x===aa[ai].x&&q.z===aa[ai].z);return [...aa.slice(0,ai+1),...bb.slice(0,bi).reverse()].filter((p,i,arr)=>!i||Math.hypot(p.x-arr[i-1].x,p.z-arr[i-1].z)>.01);}
 function finish(s){ride=null;manualPause=false;dock.hidden=true;car.position.set(s.x,0,s.z);onExit({x:s.x+2.2,z:s.z});}
 function board(destination){const from=nearest();if(!from||from.id===destination.id||ride||!canBoard())return false;beforeBoard();ride={from,to:destination,path:route(from,destination),segment:0,t:0};lookYaw=lookPitch=0;manualPause=false;toggle.textContent='Pause';car.position.set(from.x,0,from.z);dialog.close();dock.hidden=false;return true;}
 function render(){body.replaceChildren();const here=nearest(),p=document.createElement('p');p.textContent=ride?'A trip is in progress.':here?'Board at '+here.name+'. Choose your destination.':'Choose a stop for walking directions. Board when you arrive.';body.append(p);for(const s of stops){const b=document.createElement('button');b.id='tramTo-'+s.id;b.textContent=(here?'Ride to ':'Guide me to ')+s.name;b.disabled=!!ride||here?.id===s.id;b.onclick=()=>{if(here)board(s);else{guideTo({x:s.x+2.2,z:s.z,name:s.name+' tram stop'});dialog.close();}};body.append(b);}}
 function open(){pause();render();dialog.showModal();}nav.onclick=open;toggle.onclick=()=>{manualPause=!manualPause;toggle.textContent=manualPause?'Resume':'Pause';};cancel.onclick=()=>{if(ride)finish(ride.from);};
 return {stops,route,open,board,get near(){return nearest()},get active(){return !!ride},get isOpen(){return dialog.open},cancel(){if(ride)finish(ride.from);},look(dx,dy){lookYaw-=dx*.004;lookPitch=Math.max(-1.1,Math.min(1.1,lookPitch-dy*.004));},update(dt,paused){if(!ride)return;let remaining=paused||manualPause?0:dt*7;while(ride&&remaining>0){const a=ride.path[ride.segment],b=ride.path[ride.segment+1],length=Math.hypot(b.x-a.x,b.z-a.z),step=Math.min(remaining,length-ride.t);ride.t+=step;remaining-=step;if(ride.t>=length){ride.segment++;ride.t=0;if(ride.segment===ride.path.length-1){finish(ride.to);return;}}}if(!ride)return;const a=ride.path[ride.segment],b=ride.path[ride.segment+1],t=ride.t/Math.hypot(b.x-a.x,b.z-a.z);car.position.set(a.x+(b.x-a.x)*t,0,a.z+(b.z-a.z)*t);car.rotation.y=Math.atan2(-(b.x-a.x),-(b.z-a.z));camera.position.set(car.position.x,2.05,car.position.z);camera.rotation.set(lookPitch,car.rotation.y+lookYaw,0);status.textContent=(manualPause||paused?'Paused · ':'Riding to ')+ride.to.name;}};
}
